8	<style>
9	:root{
10	--bg:#f6f1e8;
11	--bg-soft:#fffdf9;
12	--paper:rgba(255,255,255,.84);
13	--text:#241f1a;
14	--muted:#5b5148;
15	--muted-2:#7d6d5c;
