23	--shadow:0 20px 60px rgba(89,67,46,.10);
24	}
25	*{box-sizing:border-box}
26	html{scroll-behavior:smooth}
27	body{margin:0;font-family:"Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif;background:var(--bg);color:var(--text);line-height:1.7}
28	a{text-decoration:none;color:inherit}
29	img{max-width:100%;display:block}
30	.container{width:min(var(--max),calc(100% - 32px));margin:auto}
31	.section{padding:88px 0}
32	.eyebrow{font-size:12px;letter-spacing:.24em;text-transform:uppercase;font-weight:900;color:#8a6844}
33	.hero{position:relative;overflow:hidden;padding:82px 0 88px;background:
34	radial-gradient(circle at 15% 20%, rgba(255,255,255,.52), transparent 20%),
35	radial-gradient(circle at 80% 12%, rgba(200,132,91,.18), transparent 22%),
36	radial-gradient(circle at 68% 78%, rgba(67,82,72,.14), transparent 26%),
37	linear-gradient(135deg,#f7f1e7 0%,#efe3cf 42%,#ead7bb 100%)}
38	.hero-grid,.cards,.route-grid,.sponsor-grid,.footer-cta,.proof-grid,.meta-grid,.fit-grid,.agenda-grid,.speaker-grid{display:grid;gap:24px}
39	.hero-grid{grid-template-columns:1.08fr .92fr;gap:48px;align-items:center}
40	.meta-grid{grid-template-columns:repeat(3,1fr);margin-top:34px}
41	.cards{grid-template-columns:repeat(3,1fr);margin-top:30px}
42	.fit-grid{grid-template-columns:repeat(4,1fr);margin-top:26px}
43	.proof-grid{grid-template-columns:1.05fr .95fr;align-items:start;margin-top:28px}
44	.route-grid{grid-template-columns:repeat(2,1fr);margin-top:30px}
45	.sponsor-grid{grid-template-columns:repeat(3,1fr);margin-top:30px}
46	.footer-cta{grid-template-columns:1fr 320px;align-items:center;gap:32px}
47	.chip{display:inline-flex;align-items:center;padding:10px 18px;border-radius:999px;border:1px solid var(--gold);background:rgba(255,255,255,.72);font-weight:800;color:#6b5134;box-shadow:0 4px 20px rgba(0,0,0,.03);backdrop-filter:blur(8px)}
48	.location-badge{display:inline-flex;align-items:center;gap:5px;margin-top:10px;font-size:14px;font-weight:900;color:var(--accent);letter-spacing:.04em}
49	.headline{font-size:clamp(42px,6vw,74px);line-height:.96;font-weight:900;margin:6px 0 10px;letter-spacing:-.03em}
50	.subheadline{font-size:clamp(23px,3vw,34px);color:var(--accent);font-weight:900}
51	.lead{font-size:clamp(18px,2vw,21px);color:#4e463f;margin-top:20px;max-width:760px}
52	.btn-row{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}
53	.btn{display:inline-flex;align-items:center;justify-content:center;padding:16px 28px;border-radius:999px;font-weight:900;transition:.22s ease;border:none;cursor:pointer;font-size:16px;font-family:inherit}
54	.btn:hover{transform:translateY(-2px)}
55	.btn-primary{background:#241f1a;color:#fff;box-shadow:0 14px 34px rgba(36,31,26,.14)}
56	.btn-secondary{border:1px solid var(--gold);background:rgba(255,255,255,.75);color:#6b5134}
57	.hero-box,.card,.price-box,.route-card,.signup-card,.qr-panel,.proof-card,.fit-card,.agenda-card,.speaker-card{background:var(--paper);border:1px solid #e4d4bf;border-radius:30px;box-shadow:var(--shadow)}
58	.hero-box{padding:30px;background:rgba(255,255,255,.86)}
59	.badge{display:inline-block;background:var(--accent);color:#fff;padding:6px 12px;border-radius:999px;font-weight:900;font-size:13px}
60	.hero-box h3{margin:14px 0 8px;font-size:clamp(32px,4vw,48px);line-height:1.1}
61	.hero-box p{margin:0;color:var(--muted);font-size:18px}
62	.countdown{display:flex;flex-wrap:wrap;align-items:center;gap:12px;background:#fff3e5;border:1px solid #e8cfa8;padding:14px 20px;border-radius:18px;margin-top:22px;font-weight:900;box-shadow:0 8px 20px rgba(167,123,60,.08)}
63	.count-live{display:inline-flex;align-items:center;gap:10px}
64	.count-timer{display:inline-flex;flex-wrap:wrap;gap:10px}
65	.time-box{min-width:72px;padding:10px 12px;border-radius:14px;background:#fff;border:1px solid #ecd7b7;text-align:center;box-shadow:0 6px 16px rgba(167,123,60,.06)}
66	.time-box strong{display:block;font-size:22px;line-height:1.1;color:#7a4c2b}
67	.time-box span{display:block;margin-top:4px;font-size:12px;color:#8b7257;font-weight:800;letter-spacing:.08em}
68	.count-dot{width:10px;height:10px;border-radius:999px;background:#c44d2b;box-shadow:0 0 0 8px rgba(196,77,43,.12)}
69	.meta-card,.fit-card{padding:20px}
70	.meta-card strong{display:block;margin-top:6px;font-size:28px;line-height:1.2}
71	h2{font-size:clamp(32px,4vw,52px);margin:0 0 14px;font-weight:900;line-height:1.12;letter-spacing:-.02em}
72	.section-lead{font-size:19px;color:var(--muted);max-width:860px}
73	.card{padding:26px;transition:.22s ease}
74	.card:hover{transform:translateY(-4px)}
75	.num{width:48px;height:48px;border-radius:999px;display:grid;place-items:center;background:#f1e2cf;color:#8a6844;font-weight:900}
76	.flow-sub{margin-top:18px;font-size:12px;font-weight:900;letter-spacing:.18em;text-transform:uppercase;color:#8a6844}
77	.flow-title{margin-top:8px;font-size:28px;font-weight:900;line-height:1.15}
78	.flow-text{margin-top:12px;color:var(--muted)}
79	.highlight{background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;padding:80px 0;text-align:center}
80	.highlight .eyebrow{color:#f8dfc6}.highlight h2{color:#fff}.highlight p{max-width:860px;margin:18px auto 0;color:#faeee7;font-size:20px}
81	.price-wrap{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:start}
82	.price-box{padding:30px;background:linear-gradient(180deg,#fffaf2 0%,#f3e7d5 100%)}
83	.price{font-size:clamp(52px,7vw,78px);font-weight:900;line-height:1;margin:10px 0 4px}
84	.checklist{display:grid;gap:8px;color:#4e463f;margin-top:16px}
85	.route{background:#fffdf9;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
86	.route-card{padding:32px;background:#fff;transition:.25s ease;cursor:pointer}
87	.route-card:hover{transform:translateY(-6px);box-shadow:0 26px 60px rgba(0,0,0,.12)}
88	.entry-icon{width:200px;height:200px;border-radius:44px;background:linear-gradient(135deg,#ffffff,#f3e7d5);display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;border:1px solid #e2d2bd;box-shadow:0 14px 30px rgba(0,0,0,.08);transition:.25s;position:relative;overflow:hidden}
89	.entry-icon::after{content:"";position:absolute;inset:auto -28px -34px auto;width:110px;height:110px;border-radius:999px;background:rgba(200,132,91,.10);filter:blur(2px)}
90	.entry-emoji{display:flex;align-items:center;justify-content:center;gap:12px;font-size:70px;line-height:1}
91	.entry-emoji .accent-mark{font-size:44px;transform:translateY(-8px)}
92	.entry-emoji.team .accent-mark{font-size:42px;transform:none}
93	.route-card:hover .entry-icon{transform:scale(1.05)}
94	.entry-icon span{font-size:24px;margin-top:10px;font-weight:900;color:#5b5148;letter-spacing:.06em}
95	.route-note{margin-top:14px;padding:14px 16px;border-radius:18px;background:#f8f1e7;color:#6b5d50;font-size:14px}
96	.route-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
97	.qr-box{width:104px;height:104px;display:grid;place-items:center;text-align:center;border-radius:24px;border:1px solid #d8c6b1;background:linear-gradient(135deg,#fff 0%,#f4eadc 100%);font-size:12px;font-weight:800;color:#7a6857}
98	.sponsor{background:linear-gradient(180deg,var(--olive) 0%,var(--olive-2) 100%);color:#fff;padding:96px 0}
99	.sponsor .eyebrow{color:#d8c6b1}.sponsor .section-lead{color:#e8ddd0}
100	.sponsor-card{background:rgba(255,255,255,.06);padding:30px;border-radius:28px;border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(10px)}
101	.sponsor-card h3{margin:0;color:#f5e7d8;font-size:24px}
102	.sponsor-card .plan-tag{display:inline-block;margin-top:8px;padding:6px 10px;border-radius:999px;background:rgba(255,255,255,.10);font-size:12px;font-weight:900;color:#dfc4aa}
103	.sponsor-card ul{margin:14px 0 0;padding-left:20px;color:#f6efe8}.sponsor-card li+li{margin-top:8px}
104	.sponsor-note{max-width:720px;margin:34px auto 0;text-align:center;color:#e8ddd0;font-size:15px;line-height:1.9}
105	.booth-photo{width:100%;aspect-ratio:1/1;border-radius:20px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(255,255,255,.14)}
106	.booth-photo img{width:100%;height:100%;object-fit:cover}
107	.booth-card .plan-tag{margin-top:0}
108	.booth-desc{margin:10px 0 0;color:#f6efe8;font-size:15px;line-height:1.8}
109	.donor-list{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px;justify-content:center}
110	.donor-chip{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:14px;padding:12px 20px;color:#f6efe8;font-size:15px;font-weight:700;line-height:1.6}
111	.signup{padding:92px 0}
112	.signup-card{padding:40px;background:linear-gradient(135deg,#f8f1e7,#efe0c8)}
113	.link-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:28px}
114	.link-card{border-radius:22px;border:1px solid #ddcdb8;background:rgba(255,255,255,.75);padding:18px}
115	.link-value{margin-top:8px;word-break:break-all;font-weight:800}
116	.qr-panel{padding:24px;text-align:center;background:rgba(255,255,255,.88)}
117	.qr-real{width:224px;height:224px;margin:0 auto;border-radius:26px;background:linear-gradient(135deg,#ffffff 0%,#f4eadc 100%);border:1px solid #d8c6b1;display:grid;place-items:center;overflow:hidden}
118	.qr-real img{width:180px;height:180px}
119	.tiny-proof{margin-top:16px;font-size:12px;line-height:1.75;color:#8a7a6a}
120	.sticky{position:fixed;left:0;right:0;bottom:0;background:rgba(36,31,26,.94);backdrop-filter:blur(10px);padding:12px 16px;display:flex;justify-content:center;gap:12px;z-index:999;border-top:1px solid rgba(255,255,255,.08)}
121	.sticky a,.sticky button{background:#fff;padding:14px 22px;border-radius:999px;font-weight:900;color:#241f1a;min-width:150px;text-align:center;border:none;cursor:pointer;font-size:16px;font-family:inherit}
122	.sticky a.primary,.sticky button.primary{background:#f6d2b4}
123	.small-note{font-size:14px;color:var(--muted-2);margin-top:10px}
124	footer{padding:0 0 84px;color:#8a7a6a;text-align:center;font-size:13px}
125	
126	/* 議程 Agenda */
127	.agenda-grid{grid-template-columns:repeat(auto-fit,minmax(280px,1fr));margin-top:30px}
128	.agenda-card{padding:26px}
129	.agenda-card:hover{transform:translateY(-4px)}
130	.agenda-speaker{display:inline-block;margin-top:16px;padding:6px 14px;border-radius:999px;background:#f1e2cf;color:#6b5134;font-weight:900;font-size:14px}
131	.agenda-speaker.tbd{background:#efe6d8;color:#8a7a6a}
132	
133	/* 講師陣容 Speakers */
134	.speaker-grid{grid-template-columns:repeat(2,1fr);margin-top:30px}
135	.speaker-card{padding:22px;display:grid;grid-template-columns:132px 1fr;gap:18px;align-items:start}
136	.speaker-card:hover{transform:translateY(-4px)}
137	.speaker-photo{width:132px;aspect-ratio:1 / 1.2;border-radius:18px;background:linear-gradient(135deg,#f1e2cf,#e4d4bf);display:flex;align-items:center;justify-content:center;font-size:36px;font-weight:900;color:#8a6844;overflow:hidden;border:1px solid #e4d4bf}
138	.speaker-photo img{width:100%;height:100%;object-fit:cover;object-position:center top}
139	.speaker-name{font-size:22px;font-weight:900;color:var(--text)}
140	.speaker-title{margin-top:2px;font-size:14px;font-weight:800;color:var(--accent)}
141	.speaker-topic{margin-top:10px;padding:10px 14px;border-radius:14px;background:#f8f1e7;color:var(--muted);font-weight:800;font-size:14px;line-height:1.6}
142	.speaker-actions{margin-top:12px}
143	.btn-mini{display:inline-flex;padding:8px 16px;border-radius:999px;background:var(--accent);color:#fff;font-weight:900;font-size:13px}
144	.bio-card{scroll-margin-top:100px;padding:26px}
145	.bio-tag{display:inline-block;margin-bottom:10px;padding:5px 12px;border-radius:999px;background:#f1e2cf;color:#6b5134;font-weight:900;font-size:13px}
146	.bio-card h3{margin:0 0 8px;font-size:22px;font-weight:900}
147	.bio-card p{margin:0;color:var(--muted);font-size:15px;line-height:1.85}
148	
149	/* 報名 Modal（比照 bigtree/old 完整流程：表單→送出→成功頁→使用者主動點擊才開LINE，避免瀏覽器擋彈窗） */
150	.modal{position:fixed;inset:0;z-index:1000;display:none;align-items:center;justify-content:center;padding:16px}
151	.modal.show{display:flex}
152	.modal-bg{position:absolute;inset:0;background:rgba(36,31,26,.65);backdrop-filter:blur(8px)}
153	.modal-box{position:relative;background:#fffdf9;border-radius:24px;width:100%;max-width:460px;overflow:hidden;box-shadow:0 28px 60px -20px rgba(0,0,0,.45);animation:modalIn .25s ease;max-height:92vh;overflow-y:auto}
154	@keyframes modalIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
155	.modal-head{background:#241f1a;color:#fff;padding:20px 24px;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
156	.modal-title{font-weight:900;font-size:20px}
157	.modal-sub{font-size:13px;color:#d8c6b1;margin-top:4px}
158	.modal-close{background:transparent;border:0;color:rgba(255,255,255,.75);font-size:30px;line-height:1;cursor:pointer;padding:0;flex-shrink:0}
159	.modal-close:hover{color:#fff}
160	.modal-body{padding:22px 24px 26px}
161	.field{display:block;margin-bottom:13px}
162	.field label{display:block;font-size:11.5px;font-weight:800;letter-spacing:.14em;color:var(--muted);margin-bottom:6px}
163	.field input{width:100%;border:1px solid var(--line);border-radius:10px;padding:11px 14px;font-size:15px;font-family:inherit;outline:none;transition:.2s;background:#fffdf9;box-sizing:border-box}
164	.field input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(155,91,63,.18);background:#fff}
165	.field-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}
166	.field-check{display:flex;gap:10px;align-items:flex-start;margin-top:10px;font-size:13.5px;color:var(--muted);line-height:1.55}
167	.field-check input{width:16px;height:16px;margin-top:3px;accent-color:var(--accent);flex-shrink:0}
168	.modal-actions{display:flex;gap:10px;margin-top:22px}
169	.btn-ghost{flex:1;height:48px;border:1px solid var(--line);background:#fff;color:var(--text);font-weight:700;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;font-family:inherit}
170	.btn-ghost:hover{background:#f8f1e7}
171	.btn-submit{flex:1;height:48px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;font-weight:900;border:0;border-radius:999px;font-size:15px;cursor:pointer;transition:.2s;box-shadow:0 10px 24px -10px rgba(155,91,63,.55);font-family:inherit}
172	.btn-submit:hover{transform:translateY(-1px)}
173	.btn-submit:disabled{opacity:.6;cursor:not-allowed;transform:none}
174	.success-box{padding:32px 24px;text-align:center}
175	.success-icon{width:72px;height:72px;border-radius:50%;background:linear-gradient(135deg,#9ee9d3,#06C755);margin:0 auto 18px;display:grid;place-items:center;color:#fff;font-size:36px}
176	.success-box h3{font-size:24px;font-weight:900;color:var(--text);margin:0 0 8px}
177	.success-box>p{color:var(--muted);font-size:14.5px;margin:0 0 22px;line-height:1.7}
178	.success-line-banner{background:#e6f8ee;border:1px solid #b9d6c8;border-radius:14px;padding:18px;margin-bottom:18px;text-align:left}
179	.banner-head{font-weight:900;color:#06C755;display:flex;align-items:center;gap:8px;font-size:15px;margin-bottom:12px}
180	.btn-line-confirm{width:100%;height:50px;background:#06C755;color:#fff;font-weight:900;border:0;border-radius:12px;font-size:15px;cursor:pointer;transition:.2s;display:flex;align-items:center;justify-content:center;gap:8px;font-family:inherit}
181	.btn-line-confirm:hover{background:#04a847}
182	.btn-copy-msg{display:flex;align-items:center;justify-content:center;gap:5px;margin:10px auto 0;background:transparent;border:0;color:#06C755;font-size:13.5px;cursor:pointer;font-weight:700;font-family:inherit}
183	.btn-copy-msg:hover{text-decoration:underline}
184	.btn-close-modal{width:100%;height:42px;background:transparent;border:0;color:var(--muted);font-size:14.5px;cursor:pointer;font-weight:500;font-family:inherit}
185	.btn-close-modal:hover{color:var(--text)}
186	.type-choice-list{display:grid;gap:12px}
187	.type-choice{display:flex;align-items:center;gap:16px;padding:18px;border-radius:16px;border:1px solid var(--line);background:#fffdf9;cursor:pointer;text-align:left;transition:.2s;font-family:inherit}
188	.type-choice:hover{border-color:var(--accent);background:#fff;transform:translateY(-2px);box-shadow:0 10px 24px -12px rgba(155,91,63,.3)}
189	.type-choice-icon{font-size:30px;flex-shrink:0}
190	.type-choice-text{display:flex;flex-direction:column;gap:3px}
191	.type-choice-text strong{font-size:17px;color:var(--text)}
192	.type-choice-text small{font-size:13px;color:var(--muted)}
193	@media(max-width:640px){.field-row{grid-template-columns:1fr}}
